118	/**
119	 * Finds a log file by identifier (full path, filename, or partial match)
120	 * @param identifier - File path, name, or partial name to search for
121	 * @param type - Log type to filter by
122	 */
123	export function findLogFile(
124	  identifier: string,
125	  type: 'debug' | 'error' | 'all' = 'all',
126	): string | null {
127	  // Check if it's a full path that exists
128	  if (path.isAbsolute(identifier) && fsSync.existsSync(identifier)) {
129	    return identifier;
130	  }
131	
132	  const logDir = getLogDirectory();
133	
134	  // Check if it's a filename in the logs directory
135	  const fullPath = path.join(logDir, identifier);
136	  if (fsSync.existsSync(fullPath)) {
137	    return fullPath;
138	  }
139	
140	  // Try fuzzy matching (prefix/contains) - use sync version here since this is called from resolveLogPath
141	  const files = getLogFilesSync(type);
142	  const match = files.find((f) => f.name.includes(identifier) || f.name.startsWith(identifier));
143	
144	  return match?.path || null;
145	}
