1	import fs from 'fs';
2	import path from 'path';
3	import zlib from 'zlib';
4	
5	import logger from '../logger';
6	import Eval from '../models/eval';
7	import telemetry from '../telemetry';
8	import { createOutputMetadata, writeOutput } from '../util/index';
9	import { getLogDirectory, getLogFilesSync } from '../util/logs';
10	import type { Command } from 'commander';
11	
12	/**
13	 * Creates a compressed tar.gz file containing log files
14	 */
15	async function createLogArchive(logFiles: string[], outputPath: string): Promise<void> {
16	  return new Promise((resolve, reject) => {
17	    const output = fs.createWriteStream(outputPath);
18	    const gzip = zlib.createGzip({ level: 9 });
19	
20	    output.on('close', () => {
21	      const stats = fs.statSync(outputPath);
22	      logger.info(`Created log archive: ${outputPath} (${stats.size} bytes)`);
23	      resolve();
24	    });
25	
26	    output.on('error', reject);
27	    gzip.on('error', reject);
28	
29	    gzip.pipe(output);
30	
31	    for (const logFile of logFiles) {
32	      if (fs.existsSync(logFile)) {
33	        const fileName = path.basename(logFile);
34	        const fileContent = fs.readFileSync(logFile);
35	        const fileStats = fs.statSync(logFile);
36	
37	        // Create tar header (simplified version)
38	        const header = Buffer.alloc(512);
39	
40	        // File name (100 bytes)
41	        Buffer.from(fileName).copy(header, 0, 0, Math.min(fileName.length, 100));
42	
43	        // File mode (8 bytes) - default 644
44	        Buffer.from('0000644 ').copy(header, 100);
45	
46	        // User ID (8 bytes)
47	        Buffer.from('0000000 ').copy(header, 108);
48	
49	        // Group ID (8 bytes)
50	        Buffer.from('0000000 ').copy(header, 116);
51	
52	        // File size (12 bytes) - octal
53	        const sizeOctal = fileStats.size.toString(8).padStart(11, '0') + ' ';
54	        Buffer.from(sizeOctal).copy(header, 124);
55	
56	        // Modification time (12 bytes) - octal
57	        const mtime = Math.floor(fileStats.mtime.getTime() / 1000);
58	        const mtimeOctal = mtime.toString(8).padStart(11, '0') + ' ';
59	        Buffer.from(mtimeOctal).copy(header, 136);
60	
61	        // Checksum placeholder (8 bytes)
62	        Buffer.from('        ').copy(header, 148);
63	
64	        // Type flag (1 byte) - regular file
65	        header[156] = 0x30; // '0'
66	
67	        // Calculate checksum
68	        let checksum = 0;
69	        for (let i = 0; i < 512; i++) {
70	          checksum += header[i];
71	        }
72	        const checksumOctal = checksum.toString(8).padStart(6, '0') + '\0 ';
73	        Buffer.from(checksumOctal).copy(header, 148);
74	
75	        // Write header
76	        gzip.write(header);
77	
78	        // Write file content
79	        gzip.write(fileContent);
80	
81	        // Pad to 512-byte boundary
82	        const padding = 512 - (fileContent.length % 512);
83	        if (padding < 512) {
84	          gzip.write(Buffer.alloc(padding));
85	        }
86	      }
87	    }
88	
89	    // Write two empty 512-byte blocks to end the tar
90	    gzip.write(Buffer.alloc(1024));
91	    gzip.end();
92	  });
93	}
