95	export function exportCommand(program: Command) {
96	  const exportCmd = program.command('export').description('Export eval records or logs');
97	
98	  exportCmd
99	    .command('eval <evalId>')
100	    .description('Export an eval record to a JSON file')
101	    .option('-o, --output [outputPath]', 'Output path for the exported file')
102	    .action(async (evalId, cmdObj) => {
103	      try {
104	        let result;
105	        if (evalId === 'latest') {
106	          result = await Eval.latest();
107	        } else {
108	          result = await Eval.findById(evalId);
109	        }
110	
111	        if (!result) {
112	          logger.error(`No eval found with ID ${evalId}`);
113	          process.exitCode = 1;
114	          return;
115	        }
116	
117	        if (cmdObj.output) {
118	          await writeOutput(cmdObj.output, result, null);
119	
120	          logger.info(`Eval with ID ${evalId} has been successfully exported to ${cmdObj.output}.`);
121	        } else {
122	          const summary = await result.toEvaluateSummary();
123	          const metadata = createOutputMetadata(result);
124	          const jsonData = JSON.stringify(
125	            {
126	              evalId: result.id,
127	              results: summary,
128	              config: result.config,
129	              shareableUrl: null,
130	              metadata,
131	            },
132	            null,
133	            2,
134	          );
135	          logger.info(jsonData);
136	        }
137	
138	        telemetry.record('command_used', {
139	          name: 'export',
140	          evalId,
141	        });
142	      } catch (error) {
143	        logger.error(`Failed to export eval: ${error}`);
144	        process.exitCode = 1;
145	      }
146	    });
147	
148	  exportCmd
149	    .command('logs')
150	    .description('Collect and zip log files for debugging')
